<?php require_once '../includes/auth.php'; require_once '../includes/csrf.php'; require_once '../includes/functions.php'; if($_SERVER['REQUEST_METHOD']!=='POST') redirect('register.php'); verify_csrf(); $name=trim($_POST['name']??''); $email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL); $password=$_POST['password']??''; $phone=trim($_POST['phone']??''); if(!$name||!$email||strlen($password)<8){flash('error','Completa los datos correctamente.');redirect('register.php');} try{$stmt=db()->prepare('INSERT INTO usuarios(name,email,phone,password,role,status) VALUES(?,?,?,?,"cliente","active")');$stmt->execute([$name,$email,$phone,password_hash($password,PASSWORD_DEFAULT)]);$id=db()->lastInsertId();login_user(['id'=>$id,'name'=>$name,'email'=>$email,'role'=>'cliente']);redirect(safe_redirect($_POST['redirect']??'','index.php'));}catch(PDOException $e){flash('error','El correo ya está registrado.');redirect('register.php');}
